pages.schema:
{
  "@context": "https://schema.org",
  "@type": "HowTo",
  "name": "Comment convertir des images avec CovertConvert",
  "description": "Convertissez HEIC, WebP, AVIF et d'autres formats d'image en JPG ou PNG entièrement dans votre navigateur.",
  "step": [
    {
      "@type": "HowToStep",
      "name": "Sélectionner les fichiers",
      "text": "Déposez des fichiers image sur le convertisseur ou cliquez pour parcourir. Supporte HEIC, WebP, AVIF, TIFF, PNG, BMP et GIF."
    },
    {
      "@type": "HowToStep",
      "name": "Choisir le format de sortie",
      "text": "Sélectionnez JPEG pour des fichiers plus petits ou PNG pour une qualité sans perte. Ajustez la qualité JPEG si désiré."
    },
    {
      "@type": "HowToStep",
      "name": "La conversion se fait localement",
      "text": "Votre navigateur traite les images en utilisant WebAssembly. Les fichiers ne quittent jamais votre appareil."
    },
    {
      "@type": "HowToStep",
      "name": "Télécharger les résultats",
      "text": "Les fichiers convertis se téléchargent automatiquement. Plusieurs fichiers sont regroupés dans une archive ZIP."
    }
  ]
}
